"""1Password writes (J-0643, D-1085/D-1086): a new password is generated by op itself (``--generate-password``, no
whole-item template, so passkeys and files survive and no password crosses this process); an authenticator key
reaches op only inside a mode-600 template file in a private temp dir that is gone afterwards, never argv, and a
failed write keeps no copy of it in the error. A fake ``op`` records argv and what the template held."""

from __future__ import annotations

import copy
import json
import os
import stat

import pytest

from agent.vault_backends import onepassword
from agent.vault_backends.base import BackendError
from agent.vault_backends.onepassword import (
    OnePasswordLoginBackend, PasskeyItem, TotpAlreadySet, clear_list_cache, totp_key)

pytestmark = pytest.mark.platforms("posix")  # the fake op is a shebang script

GENERATED = "op-Generated-7%pw"
KEY_URI = "otpauth://totp/Shop:jane?secret=JBSWY3DPEHPK3PXP&issuer=Shop"

_FAKE_OP = r'''#!/usr/bin/env python3
import json, os, stat, sys
here = os.path.dirname(os.path.abspath(__file__))
argv = sys.argv[1:]
entry = {"argv": argv}
if "--template" in argv:
    path = argv[argv.index("--template") + 1]
    entry.update(path=path, template=open(path, encoding="utf-8").read(),
                 file_mode=stat.S_IMODE(os.stat(path).st_mode), dir_mode=stat.S_IMODE(os.stat(os.path.dirname(path)).st_mode))
open(os.path.join(here, "op.log"), "a").write(json.dumps(entry) + "\n")
item_path = os.path.join(here, "item.json")
item = json.load(open(item_path, encoding="utf-8"))
if os.path.exists(os.path.join(here, "fail")) and "--template" in argv:  # op echoing the template
    values = [f.get("value", "") for f in json.loads(entry["template"]).get("fields", [])]
    sys.stderr.write("[ERROR] invalid field value: " + " ".join(values) + "\n"); sys.exit(1)
gen = [a for a in argv if a.startswith("--generate-password=")]
if argv[:2] == ["item", "get"]:
    print(json.dumps(item)); sys.exit(0)
if argv[:2] == ["item", "create"]:
    user = [a for a in argv if a.startswith("username=")][0].split("=", 1)[1]
    created = {"id": "new-item", "vault": {"id": "vault-h", "name": "Hermes"}, "category": "LOGIN",
               "fields": [{"id": "username", "purpose": "USERNAME", "type": "STRING", "value": user},
                          {"id": "password", "purpose": "PASSWORD", "type": "CONCEALED", "value": "op-Generated-7%pw"}]}
    open(item_path, "w", encoding="utf-8").write(json.dumps(created))
    print(json.dumps(created)); sys.exit(0)
if argv[:2] == ["item", "edit"] and gen:
    for f in item["fields"]:
        if f.get("purpose") == "PASSWORD":
            f["value"] = "op-Generated-7%pw"
    open(item_path, "w", encoding="utf-8").write(json.dumps(item)); print(json.dumps(item)); sys.exit(0)
if argv[:2] == ["item", "edit"]:
    open(item_path, "w", encoding="utf-8").write(entry["template"])
    print(entry["template"]); sys.exit(0)
sys.exit(2)
'''

_ITEM = {"id": "abc", "title": "Shop", "category": "LOGIN", "vault": {"id": "vault-123"},
         "urls": [{"href": "https://shop.example/login", "primary": True}],
         "fields": [{"id": "username", "type": "STRING", "purpose": "USERNAME", "label": "username", "value": "jane"},
                    {"id": "password", "type": "CONCEALED", "purpose": "PASSWORD", "label": "password",
                     "value": "old-password"},
                    {"id": "notesPlain", "type": "STRING", "purpose": "NOTES", "label": "notesPlain", "value": "n"}]}

# What a real item carries besides the login: custom sections and fields, several websites, a file, tags.
_RICH = dict(copy.deepcopy(_ITEM), tags=["shopping"], additional_information="jane",
             sections=[{"id": "s1", "label": "Recovery"}],
             urls=[{"href": "https://shop.example/login", "primary": True}, {"label": "app", "href": "https://m.shop.example"}],
             files=[{"id": "f1", "name": "invoice.pdf", "size": 1234, "content_path": "/v1/vaults/x/items/abc/files/f1"}])
_RICH["fields"] = _ITEM["fields"] + [
    {"id": "q1", "section": {"id": "s1", "label": "Recovery"}, "type": "CONCEALED", "label": "pin", "value": "4711"},
    {"id": "q2", "section": {"id": "s1", "label": "Recovery"}, "type": "EMAIL", "label": "backup mail", "value": "a@b.c"}]


@pytest.fixture
def op(tmp_path, monkeypatch):
    exe = tmp_path / "op"
    exe.write_text(_FAKE_OP, encoding="utf-8")
    exe.chmod(exe.stat().st_mode | stat.S_IXUSR)
    (tmp_path / "item.json").write_text(json.dumps(_ITEM), encoding="utf-8")
    monkeypatch.setenv("HERMES_HOME", str(tmp_path / ".hermes"))
    clear_list_cache()
    backend = OnePasswordLoginBackend({"enabled": True, "binary_path": str(exe)})
    backend._service_token = "service-token"

    def calls():
        log = tmp_path / "op.log"
        return [json.loads(line) for line in log.read_text(encoding="utf-8").splitlines()] if log.exists() else []

    def use(item):
        (tmp_path / "item.json").write_text(json.dumps(item), encoding="utf-8")
    yield backend, calls, tmp_path, use
    clear_list_cache()


def _private_template(call):
    assert call["file_mode"] == 0o600 and call["dir_mode"] == 0o700
    assert not os.path.exists(call["path"]) and not os.path.exists(os.path.dirname(call["path"]))
    return json.loads(call["template"])


def test_a_new_item_gets_an_op_generated_password_and_no_password_crosses_argv_or_a_file(op):
    backend, calls, _, _ = op
    handle = backend.generate_login("", origin="https://shop.example", username="jane@x.test", title="Shop")
    assert handle == "op:vault-h:new-item"
    (create,) = calls()
    assert create["argv"][:8] == ["item", "create", "--category", "login", "--vault", "Hermes", "--title", "Shop"]
    assert "--generate-password=letters,digits,symbols,20" in create["argv"] and "--template" not in create["argv"]
    assert create["argv"][create["argv"].index("--url") + 1] == "https://shop.example"
    assert "username=jane@x.test" in create["argv"] and not any(GENERATED in a for a in create["argv"])
    assert backend.resolve_password(handle) == GENERATED  # read back through the ordinary path


def test_an_existing_item_is_edited_with_only_the_generate_flag_so_a_passkey_survives(op):
    backend, calls, _, use = op
    use(_RICH)
    assert backend.generate_login("op:vault-123:abc", origin="https://shop.example", length=12, symbols=False) == \
        "op:vault-123:abc"
    (edit,) = calls()  # no `item get --reveal`, no template: nothing but the password field can change
    assert edit["argv"] == ["item", "edit", "abc", "--vault", "vault-123", "--generate-password=letters,digits,12"]
    assert backend.resolve_password("op:vault-123:abc") == GENERATED


def test_the_template_is_made_in_shared_memory_when_there_is_one(op, monkeypatch):
    backend, calls, tmp_path, _ = op
    shm = tmp_path / "shm"
    shm.mkdir()
    monkeypatch.setattr(onepassword, "_SHM", str(shm))
    backend.add_totp("op:vault-123:abc", KEY_URI)
    assert calls()[-1]["path"].startswith(str(shm) + os.sep)
    _private_template(calls()[-1])


def test_a_totp_write_round_trips_every_other_field_url_section_and_file_reference(op):
    backend, calls, _, use = op
    use(_RICH)
    assert backend.add_totp("op:vault-123:abc", KEY_URI) is True
    saved = _private_template(calls()[-1])
    expected = copy.deepcopy(_RICH)
    expected["fields"].append({"id": "TOTP_hermes", "type": "OTP", "label": "one-time password", "value": KEY_URI})
    assert saved == expected
    assert not any(KEY_URI in a for a in calls()[-1]["argv"])


@pytest.mark.parametrize("extra", [{"id": "pk1", "type": "PASSKEY", "label": "Passkey"},
                                   {"id": "x", "type": "STRING", "label": "My passkey", "value": ""},
                                   {"id": "y", "type": "SOMETHING_NEW", "label": "n", "value": "v"},
                                   {"id": "z", "type": "UNKNOWN", "label": "n", "value": "v"}])
def test_an_item_that_may_hold_a_passkey_is_never_written(op, extra):
    backend, calls, _, use = op
    use(dict(_ITEM, fields=_ITEM["fields"] + [extra]))
    with pytest.raises(PasskeyItem) as refused:
        backend.add_totp("op:vault-123:abc", KEY_URI)
    assert refused.value.error_type == "item_has_passkey"
    assert [c["argv"][1] for c in calls()] == ["get"]


def test_a_failed_totp_write_keeps_no_copy_of_the_key(op):
    backend, _, tmp_path, _ = op
    (tmp_path / "fail").write_text("", encoding="utf-8")
    with pytest.raises(BackendError) as failed:
        backend.add_totp("op:vault-123:abc", KEY_URI)
    exc = failed.value
    for text in (exc.detail, str(exc), exc.message(), json.dumps(exc.result())):
        assert KEY_URI not in text
    assert "invalid field value" in exc.detail  # op's own words are kept for classification


def test_totp_is_added_once_and_a_key_hermes_did_not_write_is_never_overwritten(op):
    backend, calls, _, use = op
    assert backend.add_totp("op:vault-123:abc", KEY_URI) is True
    otp = [f for f in _private_template(calls()[-1])["fields"] if f["type"] == "OTP"]
    assert [f["value"] for f in otp] == [KEY_URI]
    writes = len(calls())
    # the same key again (shown as spaced text this time): nothing written
    assert backend.add_totp("op:vault-123:abc", "jbsw y3dp ehpk 3pxp") is False
    assert [c["argv"][1] for c in calls()[writes:]] == ["get"]
    # a key the user (or another tool) put in: its id is not Hermes's
    use(dict(_ITEM, fields=_ITEM["fields"] + [{"id": "TOTP_user", "type": "OTP", "label": "otp", "value": KEY_URI}]))
    with pytest.raises(TotpAlreadySet):
        backend.add_totp("op:vault-123:abc", "KRSXG5CTMVRXEZLUKN2XAZLSKNSWC4TF")
    assert all(c["argv"][1] == "get" for c in calls()[writes:])


def test_an_unconfirmed_key_hermes_wrote_is_replaced_and_kept_as_previous(op):
    backend, calls, _, use = op
    old = "otpauth://totp/Shop:jane?secret=KRSXG5CTMVRXEZLUKN2XAZLSKNSWC4TF"
    use(dict(_ITEM, fields=_ITEM["fields"] + [{"id": "TOTP_hermes", "type": "OTP", "label": "one-time password",
                                               "value": old}]))
    assert backend.add_totp("op:vault-123:abc", "JBSWY3DPEHPK3PXP") is True
    fields = _private_template(calls()[-1])["fields"]
    assert [(f["type"], f["value"]) for f in fields if f["id"] == "TOTP_hermes"] == [("OTP", "JBSWY3DPEHPK3PXP")]
    (previous,) = [f for f in fields if f["id"].startswith("TOTP_prev_")]
    assert previous["type"] == "CONCEALED" and previous["value"] == old
    assert previous["label"] == "previous authenticator key (unconfirmed)"


def test_an_empty_one_time_password_field_is_not_a_held_key(op):
    backend, calls, _, use = op
    use(dict(_ITEM, fields=_ITEM["fields"] + [{"id": "TOTP_user", "type": "OTP", "label": "otp", "value": ""}]))
    assert backend.add_totp("op:vault-123:abc", KEY_URI) is True
    otp = [f for f in _private_template(calls()[-1])["fields"] if f["type"] == "OTP"]
    assert [(f["id"], f["value"]) for f in otp] == [("TOTP_user", KEY_URI)]  # filled, no second field


def test_a_malformed_key_candidate_is_no_key_and_its_parser_text_is_not_raised():
    assert totp_key("otpauth://[JBSWY3DPEHPK3PXP]/totp") == ""
    assert totp_key("otpauth://totp/x?secret=jbsw y3dp") == "JBSWY3DP"
